import {sampleRoofers} from './uniqueness.mjs';import {originalRows,variantSettings} from './section-variants.mjs';import {regenerate,saveGeneration} from '../../src/generation.js';
export function mediaSamples(){const roofs=sampleRoofers(),colors=['#95613d','#326b78','#78603c'];for(let i=0;i<roofs.length;i++){const f=roofs[i];f.settings=saveGeneration({...f.settings,color:colors[i]},f.settings,f.id,f.slug);Object.assign(f.row,{settings:JSON.stringify(f.settings),published:JSON.stringify(f.settings)});}const original=originalRows.find(x=>JSON.parse(x.row.settings).designKit==='hvac').row,existing=[];
for(const [key,name,city,style,color,phone] of [['cobalt-heron','Sample Fictional Cobalt Heron HVAC','Irvine','bold','#326778','9495550104'],['ochre-willow','Sample Fictional Ochre Willow HVAC','Riverside','fresh','#885336','9515550105']]){const s=variantSettings(original,style,'b',false);s.name=name;s.area=city;s.serviceAreas=[{city,radiusMiles:null}];s.phone=phone;s.color=color;s.email='';s.experience='';s.license='';s.hours='';s.showOwner=false;s.showProjects=false;s.effects.projectMap=false;s.services=s.services.slice(key==='cobalt-heron'?0:2,key==='cobalt-heron'?2:4);const id='sample-fictional-'+key+'-'+city.toLowerCase(),settings=regenerate(s,id,id,{existing});existing.push({id,settings});roofs.push({id,slug:id,isSample:true,fictional:true,city,settings,row:{...original,id,slug:id,name,settings:JSON.stringify(settings),published:JSON.stringify(settings),status:'published'}});}return roofs;}
